import{_ as r,o as a,c as i,a3 as s}from"./chunks/framework.B5WAEDB7.js";const o="/assets/images/n41Azff.png",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/reverse-proxy.md","filePath":"core-concepts/reverse-proxy.md"}'),t={name:"core-concepts/reverse-proxy.md"};function n(l,e,c,p,d,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<h2 id="reverse-proxy-web-server" tabindex="-1">Reverse proxy (web server) <a class="header-anchor" href="#reverse-proxy-web-server" aria-label="Permalink to &quot;Reverse proxy (web server)&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Reverse proxy (web server).</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p align="center"><img src="'+o+'"><br><i><a href="https://upload.wikimedia.org/wikipedia/commons/6/67/Reverse_proxy_h2g2bob.svg">Source: Wikipedia</a></i><br></p><p>A reverse proxy is a web server that centralizes internal services and provides unified interfaces to the public. Requests from clients are forwarded to a server that can fulfill it before the reverse proxy returns the server&#39;s response to the client.</p><p>Additional benefits include:</p><ul><li><strong>Increased security</strong> - Hide information about backend servers, blacklist IPs, limit number of connections per client</li><li><strong>Increased scalability and flexibility</strong> - Clients only see the reverse proxy&#39;s IP, allowing you to scale servers or change their configuration</li><li><strong>SSL termination</strong> - Decrypt incoming requests and encrypt server responses so backend servers do not have to perform these potentially expensive operations <ul><li>Removes the need to install <a href="https://en.wikipedia.org/wiki/X.509" target="_blank" rel="noreferrer">X.509 certificates</a> on each server</li></ul></li><li><strong>Compression</strong> - Compress server responses</li><li><strong>Caching</strong> - Return the response for cached requests</li><li><strong>Static content</strong> - Serve static content directly <ul><li>HTML/CSS/JS</li><li>Photos</li><li>Videos</li><li>Etc</li></ul></li></ul><h3 id="load-balancer-vs-reverse-proxy" tabindex="-1">Load balancer vs reverse proxy <a class="header-anchor" href="#load-balancer-vs-reverse-proxy" aria-label="Permalink to &quot;Load balancer vs reverse proxy&quot;">​</a></h3><ul><li>Deploying a load balancer is useful when you have multiple servers. Often, load balancers route traffic to a set of servers serving the same function.</li><li>Reverse proxies can be useful even with just one web server or application server, opening up the benefits described in the previous section.</li><li>Solutions such as NGINX and HAProxy can support both layer 7 reverse proxying and load balancing.</li></ul><h3 id="disadvantage-s-reverse-proxy" tabindex="-1">Disadvantage(s): reverse proxy <a class="header-anchor" href="#disadvantage-s-reverse-proxy" aria-label="Permalink to &quot;Disadvantage(s): reverse proxy&quot;">​</a></h3><ul><li>Introducing a reverse proxy results in increased complexity.</li><li>A single reverse proxy is a single point of failure, configuring multiple reverse proxies (ie a <a href="https://en.wikipedia.org/wiki/Failover" target="_blank" rel="noreferrer">failover</a>) further increases complexity.</li></ul><h3 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h3><ul><li><a href="https://www.nginx.com/resources/glossary/reverse-proxy-vs-load-balancer/" target="_blank" rel="noreferrer">Reverse proxy vs load balancer</a></li><li><a href="https://www.nginx.com/blog/inside-nginx-how-we-designed-for-performance-scale/" target="_blank" rel="noreferrer">NGINX architecture</a></li><li><a href="http://www.haproxy.org/download/1.2/doc/architecture.txt" target="_blank" rel="noreferrer">HAProxy architecture guide</a></li><li><a href="https://en.wikipedia.org/wiki/Reverse_proxy" target="_blank" rel="noreferrer">Wikipedia</a></li></ul>',12)])])}const f=r(t,[["render",n]]);export{h as __pageData,f as default};
